-- =============================================================================
-- SETUP CATALOG RULES & ABBREVIATIONS FOR CONSISTENCY CHECK ENGINE
-- =============================================================================
CREATE TABLE IF NOT EXISTS ref_abbreviations (
  id SERIAL PRIMARY KEY,
  abv VARCHAR(50) NOT NULL UNIQUE,
  full_text VARCHAR(255) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS ref_templates (
  id SERIAL PRIMARY KEY,
  code VARCHAR(10) NOT NULL UNIQUE,
  name VARCHAR(100) NOT NULL,
  prefix VARCHAR(10) NOT NULL,
  mandatory_fields JSONB NOT NULL,
  recommended_fields JSONB NOT NULL,
  default_uom VARCHAR(20),
  description TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

